class Solution {
    static long long key(int x, int y) {
        return ((long long)x << 32) ^ (unsigned int)y;
    }
public:
    bool isRectangleCover(vector<vector<int>>& rectangles) {
        if (rectangles.empty()) return false;
        int minX = INT_MAX, minY = INT_MAX;
        int maxX = INT_MIN, maxY = INT_MIN;
        long long area = 0;
        unordered_set<long long> corners;
        auto toggle = [&](int x, int y) {
            long long point = key(x, y);
            if (!corners.insert(point).second) corners.erase(point);
        };
        for (const auto& r : rectangles) {
            if (r[0] >= r[2] || r[1] >= r[3]) return false;
            minX = min(minX, r[0]); minY = min(minY, r[1]);
            maxX = max(maxX, r[2]); maxY = max(maxY, r[3]);
            area += (long long)(r[2] - r[0]) * (r[3] - r[1]);
            toggle(r[0], r[1]); toggle(r[0], r[3]);
            toggle(r[2], r[1]); toggle(r[2], r[3]);
        }
        if (area != (long long)(maxX - minX) * (maxY - minY))
            return false;
        return corners.size() == 4 &&
               corners.count(key(minX, minY)) &&
               corners.count(key(minX, maxY)) &&
               corners.count(key(maxX, minY)) &&
               corners.count(key(maxX, maxY));
    }
};
